import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"CDN 直觉","description":"","frontmatter":{"title":"CDN 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cdn-intuition.md","filePath":"cs/cdn-intuition.md","lastUpdated":1789023840000}'),h={name:"cs/cdn-intuition.md"};function E(D,a,T,_,u,A){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="cdn-直觉" tabindex="-1">CDN 直觉 <a class="header-anchor" href="#cdn-直觉" aria-label="Permalink to &quot;CDN 直觉&quot;">​</a></h1><div class="epigraph"><p>把可缓存的对象复制到离用户近的节点，用 DNS 或任播把请求导到边；源站仍是权威。</p><footer>—— 据 Nygren, Sitaraman and Sun, The Akamai Network, CACM 2010；Kurose and Ross 对 CDN 的整理</footer></div><p><a href="/cs/http-tls-entry">上一课</a>要求对象经真实信道取出，但信道仍可能跨过半个地球。<a href="/cs/http-tls-entry">HTTP</a> 的 GET 与缓存头允许复制表示。<a href="/cs/dns">DNS</a> 可以把同一名字解析到不同地址。缺口是 <strong>CDN 直觉</strong>：边缓存 + 请求导向，不是新的 TCP 拥塞公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单源受 <a href="/cs/lpm">LPM</a> 与跨洋 RTT 限制，慢启动让短对象更惨。若每个用户都回源，拥塞窗口再好也救不了距离。CDN：在 ISP 附近放缓存，命中则边节点应答；未命中回源再填。导向：按地理位置或网络度量，用 DNS 答不同 A 记录，或任播同一地址。缺口是这套分工。</p><p>本课不把一致性哈希环的全部论文证明写完。</p><p><span class="marginnote">缓存的是 HTTP 表示，遵守 Cache-Control。动态个性化请求仍回源。证书在边上要能出示源的名字，部署与上一课的真实性要求咬合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发布者把源交给 CDN。用户解析 <code>www</code> 得到边节点 IP，<a href="/cs/http-tls-entry">TLS 入口</a>意义上仍要认证该名字。GET 命中则不再走源站磁盘——像 <a href="/cs/buffer-dirty">页 Cache</a> 但对象在另一台机器。失效：TTL 或显式清洗。</p>',9)),(e(),l(p,null,{default:r(()=>[c(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%22%5D%20--%3E%20DNS%5B%22%E5%AF%BC%E5%90%91%3A%20DNS%20%E6%88%96%E4%BB%BB%E6%92%AD%22%5D%0A%20%20DNS%20--%3E%20EDGE%5B%22%E8%BE%B9%E7%BC%93%E5%AD%98%22%5D%0A%20%20EDGE%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%3A%20%E7%9B%B4%E6%8E%A5%E5%BA%94%E7%AD%94%22%5D%0A%20%20EDGE%20--%3E%20ORIGIN%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%3A%20%E5%9B%9E%E6%BA%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CDN 把应用层缓存插进端到端路径：对缓存命中，真正的「文件端」变成边节点，源站的端到端校验发生在边与源之间。用户与边仍要 TLS，否则入口课的中间人问题在边上重现。与 BGP 任播：同一前缀多地通告，LPM 把用户导到拓扑近的点，故障靠路由收敛。</p><p>不替代<a href="/cs/tcp-congestion">拥塞控制</a>：边到用户仍是一条 TCP/QUIC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入具体厂商配置语言。不把视频分片协议当必修。也不把 CDN 当安全边界的充分条件。应用如何在代码里绑定传输，下一课套接字 API——网络课收到 OS 的文件与进程上。</p><p>源站仍要能承受未命中与清洗后的风暴。边节点的缓存键通常含 Host 与规范化 URL，查询串是否计入由配置决定。</p><p>后课默认：热对象可从边取。进程怎样调用内核网络栈，下一课套接字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CDN：边缓存 + DNS/任播导向，降 RTT 与源站负载。</li><li>仍遵守 HTTP 缓存语义与 TLS 名字认证。</li><li>编程接口是套接字的缺口。</li><li>出处：Nygren, Sitaraman and Sun, <em>CACM</em> 2010；Kurose and Ross。</li></ul>',9))])}const f=o(h,[["render",E]]);export{C as __pageData,f as default};
